cd /workspace && python3 - <<'EOF' > /tmp/dbg_frames.txt
import sys
sys.path.insert(0,'project')
from wire import payload,packet
D=2
print(len(payload(0,0,0,D)), packet(0,0,payload(0,0,0,D)).hex())
EOF
cat /tmp/dbg_frames.txt | head -2
cat > /tmp/dbg.c <<'EOF'
#include "epic_clean.h"
#include <stdio.h>
#include <string.h>
int main(void){
  char line[40000];
  size_t words=2;
  if(fscanf(stdin,"%zu",&words)==0) return 1;
  while(scanf("%39999s",line)==1){
    size_t n=strlen(line)/2;
    static uint8_t frame[9000];
    for(size_t i=0;i<n;i++){ unsigned v; char b[3]={0,0,0}; memcpy(b,line+2*i,2); sscanf(b,"%02x",&v); frame[i]=(uint8_t)v; }
    epic_wire_t w;
    bool ok=epic_wire_validate(frame,n,words,&w);
    printf("len=%zu ok=%d psn=%u qpn=%x ack=%d plen=%zu\n", n, ok?1:0, w.psn, w.qpn, w.is_ack?1:0, w.payload_len);
    printf("  icrc stored=%08x computed=%08x  ipcksum field=%04x computed=%04x\n",
      (unsigned)(frame[n-4]|frame[n-3]<<8|frame[n-2]<<16|frame[n-1]<<24), epic_compute_icrc(frame,n),
      (frame[24]<<8)|frame[25], ({uint8_t h[20]; memcpy(h,frame+14,20); h[10]=0;h[11]=0; epic_ipv4_checksum(h,20);});
  }
  return 0;
}
EOF
gcc -std=gnu11 -O1 -Iproject/include /tmp/dbg.c project/src/roce_packet.c project/src/sha256.c -o /tmp/dbg 2>&1 | head -20
tail -1 /tmp/dbg_frames.txt | cut -d' ' -f2 > /tmp/one.hex && echo "2 $(< /tmp/one.hex tr -d '\n')" | /tmp/dbg
